/* eslint-disable no-undef */
import { Component, Event, EventEmitter, Host, Prop, h } from '@stencil/core';
import { ProgressCircleBackground, ProgressCircleVariants, Severity } from '../../types';

@Component({
  tag: 'groupui-progress-circle',
  styleUrl: 'progress-circle.scss',
  shadow: true,
})
export class ProgressCircle {
  /**
   * Defines if the loading indicator is visible.
   */
  @Prop() readonly displayed: boolean;

  /**
   * Defines the percentage of the progress [only progress circle].
   */
  @Prop({ reflect: true }) readonly progress: number = 0;

  /**
   * Defines the color of the backdrop
   */
  @Prop({ reflect: true }) readonly background: ProgressCircleBackground = 'light';

  /**
   * Severity of the loading-spinner
   */
  @Prop({ reflect: true }) readonly severity: Severity = 'none';

  /**
   * Variant of the progress-circle
   */
  @Prop({ reflect: true }) readonly variant: ProgressCircleVariants = 'primary';

  /**
   * Dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private calcProgress(): number {
    if (this.progress == null) {
      return 0;
    }
    return Math.max(Math.min(Math.round(this.progress), 100), 0);
  }

  private calcStrokeDashArray(): string {
    if (this.progress == null || this.progress < 0) {
      return '0,100';
    }
    const radius = 15;
    const percentage = (this.progress * 2 * Math.PI * radius) / 100;
    return `${percentage},100`;
  }

  render() {
    return (
      <Host>
        {this.displayed && (
          <div class="backdrop">
            <div id="progress-circle">
              <div class="circle-progress circle-progress--animation">
                <div class="circle-progress__label">{this.calcProgress()}%</div>
                <svg class="circle-progress__svg" viewBox="0 0 35 35">
                  <circle class="svg__background" cx="17.5" cy="17.5" r="15" />
                  <circle class="svg__fill" cx="17.5" cy="17.5" r="15" stroke-dasharray={this.calcStrokeDashArray()} />
                </svg>
              </div>
            </div>
          </div>
        )}
      </Host>
    );
  }
}
